  gap: 10px;
  pointer-events: auto;
}

.timechip {
  padding: 8px 12px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.2em;
  color: #bfeaff;
  background: var(--panel);
  border: 1px solid rgba(49, 230, 255, 0.24);
}

.iconbtn {
  width: 34px;
  height: 34px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(6, 10, 18, 0.6);
  color: #cfe9ff;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
}

.iconbtn:hover { background: rgba(49, 230, 255, 0.16); border-color: var(--cyan); }
.iconbtn.off { color: #5e6d80; }

.minimap-wrap {
  position: absolute;
  left: 30px;
  bottom: 30px;
  width: clamp(150px, 15vw, 214px);
  padding: 7px;
  background: rgba(5, 9, 16, 0.7);
  border: 1px solid rgba(49, 230, 255, 0.24);
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 14px 100%, 0 calc(100% - 14px));
  backdrop-filter: blur(8px);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

#minimap { display: block; width: 100%; height: auto; aspect-ratio: 1; }

.map-label {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 3px 2px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: #9dc9dc;
  border-top: 1px solid rgba(49, 230, 255, 0.16);
  margin-top: 6px;
}
.map-label span:last-child { color: var(--cyan); }

.speedo-wrap {
  position: absolute;
  right: 26px;
  bottom: 26px;
  width: clamp(128px, 13vw, 178px);
  filter: drop-shadow(0 10px 24px rgba(0, 0, 0, 0.35));
}

#speedo { display: block; width: 100%; height: auto; }

.bars {
  position: absolute;
  left: 50%;
  bottom: 32px;
  transform: translateX(-50%);
  display: grid;
  gap: 7px;
  width: min(280px, 24vw);
}

.bar { display: flex; align-items: center; gap: 9px; }
.bar label { width: 48px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.16em; color: #8fa6ba; text-align: right; }
.bar .track {
  position: relative;
  flex: 1;
  height: 8px;
  background: rgba(255, 255, 255, 0.09);
  border: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
  transform: skewX(-18deg);
}
.bar .track i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background: linear-gradient(90deg, #41ffa4, #18c9ff);
  box-shadow: 0 0 12px rgba(65, 255, 164, 0.6);
  transition: width 0.15s ease, background 0.3s;
}
.bar .track.boost i { background: linear-gradient(90deg, #31e6ff, #ff3ba7); box-shadow: 0 0 12px rgba(49, 230, 255, 0.65); }
.bar .track i.low { background: linear-gradient(90deg, #ff334f, #ff7b33); box-shadow: 0 0 12px rgba(255, 51, 79, 0.65); }

.hint {
  position: absolute;
  right: 32px;
  bottom: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  color: rgba(175, 200, 218, 0.5);
}

.toast {
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translate(-50%, -8px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.3s ease;
  text-align: center;
  pointer-events: none;
}

.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast b { font-family: var(--display); font-style: italic; font-size: clamp(20px, 2.2vw, 32px); letter-spacing: 0.02em; color: #fff; text-shadow: 0 0 24px rgba(49, 230, 255, 0.5), 0 2px 0 rgba(0, 0, 0, 0.5); }
.toast span { font-family: var(--mono); font-size: 9px; letter-spacing: 0.22em; color: #a8cbdd; }
.toast.pink b { color: #ffb3da; text-shadow: 0 0 24px rgba(255, 59, 167, 0.6); }
.toast.green b { color: #8dffb5; text-shadow: 0 0 24px rgba(88, 255, 160, 0.55); }
.toast.red b { color: #ff7b8f; text-shadow: 0 0 24px rgba(255, 51, 79, 0.6); }

/* ---------- modals ---------- */
.modal {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  background: radial-gradient(circle at 50% 45%, rgba(9, 16, 28, 0.52), rgba(2, 4, 9, 0.9));
  backdrop-filter: blur(6px);
}

.modal-card, .wreck-card {
  width: min(460px, 88vw);
  padding: 38px 36px;
  text-align: center;
  background: linear-gradient(160deg, rgba(10, 18, 31, 0.95), rgba(6, 10, 18, 0.92));
  border: 1px solid var(--line);
  clip-path: polygon(0 0, calc(100% - 24px) 0, 100% 24px, 100% 100%, 24px 100%, 0 calc(100% - 24px));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.6);
  animation: rise 0.4s ease both;
}

.modal-card .eyebrow { justify-content: center; }
.modal h2, .wreck-card h2 {
  margin: 12px 0 22px;
  font-family: var(--display);
  font-style: italic;
  font-size: clamp(44px, 6vw, 72px);
  letter-spacing: -0.03em;
  background: linear-gradient(180deg, #fff, #7df2ff 55%, #ff3ba7);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.modal-actions { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 20px; }
.ghost-btn {
  padding: 1em 1.6em;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: transparent;
  color: #cfe0ee;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.14em;
  cursor: pointer;
}
.ghost-btn:hover { border-color: var(--cyan); color: #fff; }

.wreck-card { border-color: rgba(255, 51, 79, 0.4); }
.wreck-kicker { font-family: var(--mono); font-size: 10px; letter-spacing: 0.4em; color: #ff5470; }
.wreck-card h2 { background: linear-gradient(180deg, #fff, #ff8a8a 50%, #ff1f4b); -webkit-background-clip: text; background-clip: text; }
.wreck-card p { font-size: 13px; color: #c9a9b0; letter-spacing: 0.04em; }

/* ---------- touch ---------- */
#touch { position: fixed; inset: 0; z-index: 12; pointer-events: none; }
#steerPad {
  position: absolute;
  left: 24px;
  bottom: 28px;
  width: 128px;
  height: 128px;
  border-radius: 50%;
  border: 1px solid rgba(49, 230, 255, 0.3);
  background: radial-gradient(circle, rgba(49, 230, 255, 0.06), rgba(4, 8, 14, 0.4));
  pointer-events: auto;
  touch-action: none;
  display: grid;
  place-items: center;
}
#steerPad span { position: absolute; bottom: -18px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.2em; color: #7e9aae; }
.stick {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: 1px solid rgba(49, 230, 255, 0.55);
  background: radial-gradient(circle at 40% 35%, rgba(141, 247, 255, 0.5), rgba(49, 230, 255, 0.1));
  box-shadow: 0 0 24px rgba(49, 230, 255, 0.25);
  transform: translateX(0);
}
.touch-right {
  position: absolute;
  right: 20px;
  bottom: 26px;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  pointer-events: auto;
}
.touch-right button {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(8, 14, 24, 0.6);
  color: #dff5ff;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  backdrop-filter: blur(6px);
}
#btnGas { width: 78px; height: 78px; border-color: rgba(49, 230, 255, 0.6); color: #8df7ff; }
#btnBoost { border-color: rgba(255, 59, 167, 0.5); color: #ffb3da; }
.touch-right button:active, .touch-right button.down { background: rgba(49, 230, 255, 0.25); }

/* ---------- responsive ---------- */
@media (max-width: 900px) {
  .screen { align-items: flex-end; padding: 5vh 6vw 5vh; background: linear-gradient(0deg, rgba(3,5,12,0.94) 0%, rgba(3,5,12,0.55) 55%, transparent 80%); }
  .brief { display: none; }
  .controls { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px 12px; }
  h1 { font-size: clamp(62px, 18vw, 120px); }
  .facts { gap: 6vw; }
  .facts div:nth-child(4) { display: none; }
  .hint { display: none; }
  .bars { width: 150px; bottom: 118px; }
  .bar label { width: 36px; font-size: 7px; }
  .minimap-wrap { width: 116px; left: 14px; bottom: 14px; }
  .speedo-wrap { width: 108px; right: 14px; bottom: 106px; }
  .hud-left { top: 16px; left: 16px; }
  .hud-right { top: 16px; right: 16px; }
  .mission { top: 16px; width: min(280px, 58vw); padding: 8px 11px 7px; }
  .mission-head { font-size: 8px; }
  .timer { font-size: 17px; }
  .mission-foot { font-size: 7.5px; }
  .brand { font-size: 10px; }
  .cash { font-size: 25px; }
  .stars { font-size: 11px; }
}

@media (max-width: 600px) {
  .hud-left { transform: scale(0.86); transform-origin: top left; }
  .hud-right { transform: scale(0.86); transform-origin: top right; }
  .mission { top: 74px; width: 220px; }
  .minimap-wrap { width: 104px; }
  .speedo-wrap { width: 96px; bottom: 96px; }
  .bars { width: 140px; bottom: 102px; }
  .screen { padding: 4vh 5vw 4vh; }
  .facts { gap: 8vw; padding: 1vh 0; }
  .start-row { margin-top: 2.6vh; }
  .start-btn { min-width: 180px; font-size: 17px; }
  .controls { margin-top: 2vh; }
  .tagline { margin-top: 2vh; font-size: 13px; }
  .foot { display: none; }
}

