  /* ---------- neon signs ---------- */
  const signMats = []
  for (const s of signs) {
    const idx = s.fixed !== undefined ? s.fixed % SIGN_TEXTS.length : Math.floor(s.rng * SIGN_TEXTS.length)
    if (!signMats[idx]) {
      const [label, main, sub] = SIGN_TEXTS[idx]
