import * as THREE from 'three'

const vertexShader = `
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  uniform float uScale;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * uScale / max(-mv.z, 1.0);
    gl_Position = projectionMatrix * mv;
    vAlpha = aAlpha;
    vColor = aColor;
  }
`

const fragmentShader = `
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vec2 c = gl_PointCoord - vec2(0.5);
    float d = length(c);
    float a = smoothstep(0.5, 0.04, d) * vAlpha;
    if (a < 0.012) discard;
    gl_FragColor = vec4(vColor, a);
  }
`

class ParticleSystem {
  constructor(scene, max, blending) {
    this.max = max
    this.cursor = 0
    this.pool = Array.from({ length: max }, () => ({
      active: false, x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0,
      life: 0, maxLife: 1, size: 1, grow: 0, gravity: 0, drag: 0, r: 1, g: 1, b: 1,
    }))
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage))
    this.geo = geo
    this.material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: { uScale: { value: 700 } },
      transparent: true,
      depthWrite: false,
      blending,
    })
    this.points = new THREE.Points(geo, this.material)
    this.points.frustumCulled = false
    scene.add(this.points)
  }

  setViewport(height, fov) {
    this.material.uniforms.uScale.value = height / (2 * Math.tan((fov * Math.PI) / 360))
  }

  spawn(x, y, z, count, opts = {}) {
    const {
      speed = 5, spread = 0.4, size = 0.2, life = 0.7, grow = 0,
      gravity = 0, drag = 0.9, up = 3, color = new THREE.Color(1, 1, 1), alpha = 1,
    } = opts
    for (let i = 0; i < count; i++) {
      const p = this.pool[this.cursor]
      this.cursor = (this.cursor + 1) % this.max
      const a = Math.random() * Math.PI * 2
      const r = Math.random() * speed
      p.active = true
      p.x = x + (Math.random() - 0.5) * spread
      p.y = y + (Math.random() - 0.5) * spread
      p.z = z + (Math.random() - 0.5) * spread
      p.vx = Math.cos(a) * r
      p.vz = Math.sin(a) * r
      p.vy = up * (0.3 + Math.random())
      p.life = p.maxLife = life * (0.6 + Math.random() * 0.8)
      p.size = size * (0.6 + Math.random() * 0.8)
      p.grow = grow
      p.gravity = gravity
      p.drag = drag
      p.r = color.r
      p.g = color.g
      p.b = color.b
      p.alpha = alpha
    }
  }

  update(dt) {
    const pos = this.positions
    const col = this.colors
    const sizes = this.sizes
    const alphas = this.alphas
    for (let i = 0; i < this.max; i++) {
      const p = this.pool[i]
      const idx = i * 3
      if (!p.active) {
        alphas[i] = 0
        continue
      }
      p.life -= dt
      if (p.life <= 0) {
        p.active = false
        alphas[i] = 0
        continue
      }
      const damp = Math.exp(-p.drag * dt)
      p.vx *= damp
      p.vz *= damp
      p.vy = p.vy * damp - p.gravity * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      if (p.y < 0.05 && p.gravity > 0) {
        p.y = 0.05
        p.vy *= -0.32
      }
      const t = p.life / p.maxLife
      pos[idx] = p.x
      pos[idx + 1] = p.y
      pos[idx + 2] = p.z
      col[idx] = p.r
      col[idx + 1] = p.g
      col[idx + 2] = p.b
      sizes[i] = p.size * (1 + (1 - t) * p.grow)
      alphas[i] = t * p.alpha
    }
    this.geo.attributes.position.needsUpdate = true
    this.geo.attributes.aColor.needsUpdate = true
    this.geo.attributes.aSize.needsUpdate = true
    this.geo.attributes.aAlpha.needsUpdate = true
  }
}

export class Particles {
  constructor(scene) {
    this.sparks = new ParticleSystem(scene, 500, THREE.AdditiveBlending)
    this.smoke = new ParticleSystem(scene, 260, THREE.NormalBlending)
    this.smokeColor = new THREE.Color('#b9c6d4')
    this.sparkColor = new THREE.Color('#ffb54b')
    this.pink = new THREE.Color('#ff3ba7')
    this.cyan = new THREE.Color('#7defff')
  }

  setViewport(height, fov) {
    this.sparks.setViewport(height, fov)
    this.smoke.setViewport(height, fov)
  }

  burst(x, y, z, color = this.sparkColor, count = 18) {
    this.sparks.spawn(x, y, z, count, {
      speed: 11, spread: 0.35, size: 0.16, life: 0.65, gravity: 20, drag: 1.4, up: 4.5, color,
    })
  }

  smokePuff(x, y, z, count = 3) {
    this.smoke.spawn(x, y, z, count, {
      speed: 1.7, spread: 0.4, size: 0.65, life: 1.5, grow: 2.4, gravity: -0.6, drag: 1.4, up: 1.2,
      color: this.smokeColor, alpha: 0.32,
    })
  }

  pickup(x, y, z) {
    this.sparks.spawn(x, y, z, 46, {
      speed: 9, spread: 0.6, size: 0.2, life: 1.1, gravity: 5, drag: 1.1, up: 5, color: this.pink, alpha: 1,
    })
    this.sparks.spawn(x, y, z, 30, {
      speed: 6, spread: 0.4, size: 0.15, life: 0.9, gravity: 3, drag: 1.2, up: 4, color: this.cyan,
    })
  }

  update(dt) {
    this.sparks.update(dt)
    this.smoke.update(dt)
  }
}

import * as THREE from 'three'
import { createBikeMesh } from './bike.js'
import { CITY } from './world.js'

const clamp = THREE.MathUtils.clamp

export class Police {
  constructor(scene, world) {
    this.scene = scene
    this.world = world
    this.units = []
    this.markerCooldown = 0
    for (let i = 0; i < 2; i++) {
      const root = createBikeMesh({ police: true })
      root.visible = false
      scene.add(root)
      this.units.push({
        root,
        parts: root.userData,
        x: 0,
        z: 0,
        y: 0,
        yaw: 0,
        speed: 0,
        active: false,
        cooldown: 0,
        spin: 0,
        lean: 0,
        age: 0,
        stuck: 0,
      })
    }
  }

  spawn(u, player, heat) {
    let best = null
    for (let i = 0; i < 24; i++) {
      const x = CITY.roadCenters[Math.floor(Math.random() * CITY.roadCenters.length)]
      const z = CITY.roadCenters[Math.floor(Math.random() * CITY.roadCenters.length)]
      const d = Math.hypot(x - player.x, z - player.z)
      if (d > 95 && d < 190) { best = { x, z }; break }
    }
    if (!best) best = { x: player.x + 120, z: player.z + 80 }
    u.x = best.x
    u.z = best.z
    u.y = this.world.groundHeightAt(u.x, u.z)
    u.yaw = Math.atan2(player.x - u.x, player.z - u.z)
    u.speed = 20
    u.active = true
    u.age = 0
    u.stuck = 0
    u.root.visible = true
    u.root.position.set(u.x, u.y + 0.02, u.z)
    u.root.rotation.y = u.yaw
    u.cooldown = 2
  }

  update(dt, player, playerSpeed, heat, time) {
    const events = []
    let closest = 999
    let activeIndex = 0
    for (let i = 0; i < this.units.length; i++) {
      const u = this.units[i]
      u.cooldown = Math.max(0, u.cooldown - dt)
      if (heat < 2.6) {
        if (u.active) {
          u.active = false
          u.root.visible = false
        }
        continue
      }
      if (!u.active && i <= Math.floor((heat - 1) / 1.6)) {
        this.spawn(u, player, heat)
      }
      if (!u.active) continue
      activeIndex++
      u.age += dt

      const dx = player.x - u.x
      const dz = player.z - u.z
      const dist = Math.hypot(dx, dz)
      closest = Math.min(closest, dist)
      if (dist > 320) {
        this.spawn(u, player, heat)
        continue
      }

      const desired = Math.atan2(dx, dz)
      let diff = ((desired - u.yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI
      const turn = clamp(diff, -1.6 * dt, 1.6 * dt)
      u.yaw += turn
      const targetSpeed = dist < 14 ? 18 : 25 + heat * 2.5
      u.speed += (targetSpeed - u.speed) * (1 - Math.exp(-dt * 1.8))
      const fx = Math.sin(u.yaw)
      const fz = Math.cos(u.yaw)
      u.x += fx * u.speed * dt
      u.z += fz * u.speed * dt
      u.x = clamp(u.x, -this.world.bounds + 5, this.world.bounds - 5)
      u.z = clamp(u.z, -this.world.bounds + 5, this.world.bounds - 5)

      const R = 0.8
      let bumped = false
      for (const b of this.world.buildings) {
        if (u.x < b.minX - 3 || u.x > b.maxX + 3 || u.z < b.minZ - 3 || u.z > b.maxZ + 3) continue
        const cx = clamp(u.x, b.minX, b.maxX)
        const cz = clamp(u.z, b.minZ, b.maxZ)
        let ox = u.x - cx
        let oz = u.z - cz
        const d2 = ox * ox + oz * oz
        if (d2 >= R * R) continue
        let len = Math.sqrt(d2)
        if (len < 1e-4) { ox = 1; oz = 0; len = 1 }
        u.x = cx + (ox / len) * R
        u.z = cz + (oz / len) * R
        u.speed *= 0.75
        bumped = true
      }
      u.stuck = bumped ? u.stuck + dt : 0
      if (u.stuck > 3) {
        this.spawn(u, player, heat)
        continue
      }

      u.lean = THREE.MathUtils.damp(u.lean, clamp(-diff, -1, 1) * 0.32, 7, dt)
      u.spin += (u.speed * dt) / 0.52
      u.y = this.world.groundHeightAt(u.x, u.z)
      u.root.position.set(u.x, u.y + 0.02, u.z)
      u.root.rotation.y = u.yaw
      u.parts.lean.rotation.z = -u.lean
      u.parts.wheels[0].rotation.x = u.spin
      u.parts.wheels[1].rotation.x = u.spin
      u.parts.frontWheel.rotation.y = clamp(-diff, -0.3, 0.3)
      u.parts.headlight.intensity = u.parts.headlight.intensity || 0

      if (u.parts.policeLights) {
        const phase = Math.sin(time * 16 + i * 2.4)
        const red = u.parts.policeLights[0]
        const blue = u.parts.policeLights[1]
        red.color.setHex(phase > 0 ? 0xff2233 : 0x3a0008)
        blue.color.setHex(phase < 0 ? 0x2277ff : 0x060a26)
      }

      if (dist < 2.5 && u.cooldown <= 0) {
        u.cooldown = 2.2
        const nx = dx / (dist || 1)
        const nz = dz / (dist || 1)
        player.x += nx * 0.6
        player.z += nz * 0.6
        events.push({ type: 'cop', impact: 12, x: u.x, z: u.z, dist })
      }
      if (activeIndex >= 1 && dist < 45) events.currentDistance = Math.min(events.currentDistance ?? 999, dist)
    }
    if (events.currentDistance === undefined) events.currentDistance = closest
    return events
  }
}

