3:const __vite__css = ":root {
  --ink: #05070d;
  --cyan: #31e6ff;
  --pink: #ff3ba7;
  --amber: #ffb020;
  --paper: #eaf6ff;
  --muted: #8fa2b8;
  --panel: rgba(6, 10, 18, 0.62);
  --line: rgba(49, 230, 255, 0.28);
  --display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
  --ui: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "DejaVu Sans Mono", monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--ui);
  -webkit-user-select: none;
  user-select: none;
  touch-action: none;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.hidden { display: none !important; }

/* ---------- screen effects ---------- */
#fx-vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 48%, rgba(2, 4, 10, 0.38) 100%),
    linear-gradient(to bottom, rgba(4, 7, 14, 0.28), transparent 22%, transparent 76%, rgba(4, 7, 14, 0.5));
  z-index: 2;
}

#fx-speed {
  position: fixed;
  inset: -10%;
  pointer-events: none;
  opacity: 0;
  z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(49, 230, 255, 0.06) 58%, rgba(4, 7, 14, 0.5) 100%),
    repeating-conic-gradient(from 0deg at 50% 50%, rgba(255, 255, 255, 0.05) 0deg 1deg, transparent 1deg 7deg);
  filter: blur(2px);
  transition: opacity 0.25s linear;
}

#fx-flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  z-index: 20;
  background: radial-gradient(circle, rgba(255, 60, 90, 0.15), rgba(255, 30, 70, 0.55));
  mix-blend-mode: screen;
}

/* ---------- menu ---------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 3vw;
  padding: 6vh 6vw 7vh;
  background:
    linear-gradient(90deg, rgba(3, 5, 12, 0.92) 0%, rgba(3, 5, 12, 0.62) 34%, transparent 58%),
    linear-gradient(0deg, rgba(3, 5, 12, 0.9) 0%, transparent 45%);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.screen.leaving {
  opacity: 0;
  transform: scale(1.03);
  pointer-events: none;
}

.menu {
  position: relative;
  max-width: 600px;
  animation: rise 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  font-family: var(--mono);
  font-size: clamp(9px, 0.75vw, 12px);
  letter-spacing: 0.42em;
  color: var(--cyan);
  text-transform: uppercase;
  text-shadow: 0 0 18px rgba(49, 230, 255, 0.55);
}

.eyebrow span {
  width: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan));
}

.eyebrow span:last-child { background: linear-gradient(90deg, var(--cyan), transparent); }

h1 {
  margin: 2.2vh 0 0;
  font-family: var(--display);
  font-style: italic;
  font-weight: 900;
  font-size: clamp(64px, 11.5vw, 176px);
  line-height: 0.78;
  letter-spacing: -0.055em;
  text-transform: uppercase;
  display: flex;
  flex-direction: column;
  filter: drop-shadow(0 10px 28px rgba(0, 0, 0, 0.65));
}

h1 em {
  font-style: italic;
  color: transparent;
  -webkit-text-stroke: 2px rgba(234, 246, 255, 0.92);
  text-stroke: 2px rgba(234, 246, 255, 0.92);
  text-shadow: 0 0 34px rgba(49, 230, 255, 0.18);
}

h1 strong {
  font-weight: 900;
  background: linear-gradient(180deg, #fff 4%, #8df5ff 38%, #31e6ff 58%, #ff3ba7 118%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 46px rgba(49, 230, 255, 0.32);
}

.tagline {
  margin-top: 3.4vh;
  font-size: clamp(15px, 1.35vw, 21px);
  letter-spacing: 0.045em;
  color: #c6d6e6;
}

.tagline::before {
  content: "";
  display: inline-block;
  width: 30px;
  height: 2px;
  margin-right: 12px;
  vertical-align: middle;
  background: var(--pink);
  box-shadow: 0 0 14px var(--pink);
}

.facts {
  display: flex;
  gap: 2.4vw;
  margin-top: 3.2vh;
  padding: 1.5vh 0;
  border-top: 1px solid rgba(255, 255, 255, 0.13);
  border-bottom: 1px solid rgba(255, 255, 255, 0.13);
}

.facts div { display: flex; flex-direction: column; gap: 3px; }
.facts b { font-family: var(--display); font-style: italic; font-size: clamp(18px, 1.7vw, 26px); color: var(--paper); }
.facts span { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.2em; color: var(--muted); }

.controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px 18px;
  margin-top: 3vh;
  max-width: 540px;
}

.ctrl { display: flex; align-items: center; gap: 5px; }
.ctrl span { margin-left: 6px; font-size: 9.5px; letter-spacing: 0.14em; color: #9fb2c7; }

kbd {
  min-width: 24px;
  padding: 4px 6px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom-color: rgba(255, 255, 255, 0.1);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.06);
  font-family: var(--mono);
  font-size: 9px;
  color: #e6f6ff;
  text-align: center;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.start-row {
  display: flex;
  align-items: center;
  gap: 2.5vw;
  margin-top: 4vh;
}

.start-btn {
  position: relative;
  min-width: 212px;
  padding: 1.55em 3.2em;
  border: 0;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  background: linear-gradient(100deg, #31e6ff, #6ff0ff 46%, #ff3ba7 130%);
  color: #04121a;
  font-family: var(--display);
  font-style: italic;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 0 40px rgba(49, 230, 255, 0.3), 0 14px 40px rgba(0, 0, 0, 0.4);
  transition: transform 0.15s ease, box-shadow 0.2s ease, filter 0.2s ease;
}

.start-btn::after {
  content: "›";
  position: absolute;
  right: 1.05em;
  top: 50%;
  transform: translateY(-52%);
  font-size: 27px;
  color: rgba(4, 18, 26, 0.72);
}

.start-btn:hover { transform: translateY(-2px) skewX(-2deg); filter: brightness(1.08); box-shadow: 0 0 60px rgba(49, 230, 255, 0.5); }
.start-btn:active { transform: translateY(1px) scale(0.99); }
.start-btn.small { min-width: 150px; padding: 1.1em 2.2em; font-size: 15px; }

.best { display: flex; flex-direction: column; gap: 4px; }
.best span { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.24em; color: var(--muted); }
.best b { font-family: var(--display); font-style: italic; font-size: 22px; color: var(--amber); }

.foot {
  margin-top: 2.6vh;
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.22em;
  color: #62758a;
}

/* ---------- briefing card ---------- */
.brief {
  position: relative;
  width: min(330px, 26vw);
  padding: 30px 28px 34px;
  margin-bottom: 3vh;
  background: linear-gradient(160deg, rgba(9, 16, 28, 0.9), rgba(8, 12, 22, 0.68));
  border: 1px solid rgba(49, 230, 255, 0.2);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
  animation: rise 0.9s 0.15s cubic-bezier(0.2, 0.8, 0.2, 1) both;
  backdrop-filter: blur(10px);
}

.brief::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 72px;
  height: 2px;
  background: var(--pink);
