}

.brief-kicker { font-family: var(--mono); font-size: 9px; letter-spacing: 0.3em; color: var(--pink); }
.brief-title { margin-top: 10px; font-family: var(--display); font-style: italic; font-size: clamp(25px, 2.4vw, 36px); line-height: 1; letter-spacing: -0.03em; }
.brief-title em { color: var(--cyan); font-style: italic; }
.brief p { margin-top: 16px; font-size: 12px; line-height: 1.65; color: #a9bacc; }
.brief-rule { height: 1px; margin: 20px 0 16px; background: linear-gradient(90deg, rgba(255, 59, 167, 0.5), transparent); }
.brief ul { list-style: none; display: grid; gap: 11px; }
.brief li { display: flex; align-items: center; gap: 12px; font-family: var(--mono); font-size: 10px; letter-spacing: 0.08em; color: #c7d7e6; }
.brief li i { font-style: normal; color: var(--cyan); font-size: 9px; opacity: 0.8; }
.brief-stamp {
  margin-top: 26px;
  font-family: var(--display);
  font-style: italic;
  font-size: 13px;
  line-height: 1.15;
  letter-spacing: 0.03em;
  color: rgba(255, 59, 167, 0.6);
  border: 1px solid rgba(255, 59, 167, 0.35);
  padding: 8px 12px;
  width: fit-content;
  transform: rotate(-4deg);
  text-shadow: 0 0 12px rgba(255, 59, 167, 0.4);
}

@keyframes rise {
  from { opacity: 0; transform: translateY(26px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- HUD ---------- */
#hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  font-family: var(--ui);
  opacity: 1;
  transition: opacity 0.5s ease;
}

#hud.fade { opacity: 0; }

.hud-left {
  position: absolute;
  top: 30px;
  left: 32px;
  padding-left: 14px;
  border-left: 2px solid var(--cyan);
  filter: drop-shadow(0 4px 14px rgba(0, 0, 0, 0.5));
}

.brand {
  font-family: var(--display);
  font-style: italic;
  font-size: 13px;
  letter-spacing: 0.16em;
  color: #dff8ff;
  display: flex;
  align-items: center;
  gap: 8px;
}

.brand-mark { color: var(--pink); font-size: 11px; text-shadow: 0 0 10px var(--pink); }

.cash {
  margin-top: 2px;
  font-family: var(--display);
  font-style: italic;
  font-size: clamp(26px, 2.6vw, 38px);
  line-height: 1;
  letter-spacing: -0.03em;
  color: #8df7b1;
