}

.stars {
  display: flex;
  gap: 4px;
  margin-top: 7px;
  font-size: 14px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.14);
  text-shadow: none;
}

.stars i { font-style: normal; transition: color 0.2s, text-shadow 0.2s, transform 0.15s; }
.stars i.on { color: var(--amber); text-shadow: 0 0 12px rgba(255, 176, 32, 0.9); }
