  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

#minimap { display: block; width: 100%; height: auto; aspect-ratio: 1; }

.map-label {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 3px 2px;
  font-family: var(--mono);
  font-size: 8px;
