  background: linear-gradient(90deg, #41ffa4, #18c9ff);
  box-shadow: 0 0 12px rgba(65, 255, 164, 0.6);
  transition: width 0.15s ease, background 0.3s;
}
.bar .track.boost i { background: linear-gradient(90deg, #31e6ff, #ff3ba7); box-shadow: 0 0 12px rgba(49, 230, 255, 0.65); }
.bar .track i.low { background: linear-gradient(90deg, #ff334f, #ff7b33); box-shadow: 0 0 12px rgba(255, 51, 79, 0.65); }

.hint {
  position: absolute;
  right: 32px;
  bottom: 4px;
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: 0.14em;
  color: rgba(175, 200, 218, 0.5);
}

.toast {
  position: absolute;
  top: 20%;
  left: 50%;
  transform: translate(-50%, -8px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.3s ease;
  text-align: center;
